"""``workpeg ui serve --fake-cloud``: everything checked before a port is
bound.

A dev install is a peg its developer is building, served from their own
computer at ``https://<namespace>.dev.workpeg.com``. The browser gives that
page the signed-in person's whole Workpeg session, so everything this
machine can check is checked before anything is bound. A refusal is one line
of fixed words, and costs nothing.

NO TOKEN

The page signs in the way every peg page does, through the Scaffold and the
universal sign-in. So ``WORKPEG_PK`` has no job here, and nothing in this
module asks for it; it keeps its meaning for ``submit`` and ``cdn submit``.
The API, not this machine, decides what the page may reach: a developer can
change their own copy of the SDK, so nothing here is a fence, only a way to
spare them a refusal the API would give anyway.

THE NAMES

The labels no dev install may use are one list, written once in the API and
copied into the SDK as ``dev_refused_names.json`` beside this file (and into
Accounts). It is read from that file on every check, and this module keeps
no copy of it, so a label the API adds is refused by the next SDK with no
change to code. A list that cannot be read refuses every name. ``contacts``
is not on it: it is a peg the peg build builds like any other.

The address is the namespace a release of the project is built under
(``workpeg.json`` first, then the folder that holds the source) followed by
``.dev.workpeg.com``. It is never a name derived from the path given on the
command line.

WHAT A REFUSAL MAY REPEAT

Only names: a namespace, a path. Each is shown escaped when it holds anything
unprintable, the rule ``build._shown`` uses for paths, because a name read
from a file or a folder could otherwise clear the terminal (``ESC[2J``) or
forge a second line.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Mapping

#: The SDK's copy of the API's list of labels no dev install may use.
REFUSED_NAMES = Path(__file__).with_name("dev_refused_names.json")

#: What follows the namespace in a dev install's address.
DEV_SUFFIX = ".dev.workpeg.com"

#: The only port a dev install is served on. The API admits a dev page's
#: origin only with no port in it, so any other could never be used.
DEV_PORT = 443

#: Plain ``serve``'s own choice of interface. A dev page's server makes that
#: choice itself, per OS (:mod:`workpeg.ui.devserve`), so the variable is
#: refused rather than read.
BIND_HOST_ENV = "WORKPEG_BIND_HOST"

REFUSED_NAME = (
    "{name} is a name Workpeg keeps for its own use, so no peg is tested "
    'under it. Set another "namespace" in its workpeg.json.')
LIST_UNREADABLE = (
    "The SDK's list of the names Workpeg keeps cannot be read, so every "
    "name is refused. Reinstall workpeg.")
NO_NAMESPACE = (
    'This project has no namespace. Set "namespace" in its workpeg.json.')
BIND_HOST_REFUSED = (
    f"A dev page's server chooses where it listens. Unset {BIND_HOST_ENV}.")
PORT_REFUSED = (
    f"A dev page is served on port {DEV_PORT} only: the API admits a dev "
    f"page's address with no port in it. Drop --port.")
PEG_NAMESPACE = (
    "A dev page takes its namespace from the project, as a release does. "
    "Drop --peg-namespace.")
PREBUILT = (
    "{path} has no main.py. Dev mode builds your Python itself: pass the "
    "project folder or its .py file.")
NOT_SOURCE = (
    "{path} is not a .py file or a project folder. Dev mode builds your "
    "Python itself.")
MISSING = "{path} does not exist."


class DevModeRefused(Exception):
    """Dev mode will not start. ``str()`` is the one line to print."""


@dataclass(frozen=True)
class DevPlan:
    """What the checks found, for the dev server to act on: the source and
    the namespace that passed, and nothing else."""

    entry: Path
    watch: Path
    namespace: str

    @property
    def domain(self) -> str:
        """The address the dev install is served at."""
        return self.namespace + DEV_SUFFIX


def _refused() -> "tuple[frozenset, tuple]":
    """``(labels, prefixes)`` from the SDK's copy of the list, read now."""
    try:
        data = json.loads(REFUSED_NAMES.read_text(encoding="utf-8"))
        labels, prefixes = data["labels"], data["prefixes"]
    except (OSError, ValueError, TypeError, KeyError):
        raise DevModeRefused(LIST_UNREADABLE) from None
    if not (isinstance(labels, list) and isinstance(prefixes, list)
            and all(isinstance(item, str) for item in labels + prefixes)):
        raise DevModeRefused(LIST_UNREADABLE)
    return frozenset(labels), tuple(prefixes)


def is_refused_label(name: str) -> bool:
    """True for a name on the list, or one starting with a listed prefix,
    ignoring case. Raises :class:`DevModeRefused` when the list cannot be
    read, so a broken install refuses rather than admits."""
    labels, prefixes = _refused()
    value = name.lower()
    return value in labels or value.startswith(prefixes)


def _q(name: object) -> str:
    """A name as a refusal repeats it: quoted, and escaped when it holds
    anything unprintable (:func:`workpeg.terminal.shown`, the rule
    ``build._shown`` applies to paths), when it comes quoted already."""
    from workpeg.terminal import shown

    text = str(name)
    value = shown(text)
    return f"'{text}'" if value == text else value


def _source(source: str) -> "tuple[Path, Path]":
    """``(entry, watch)``: the .py file to build and what to watch."""
    path = Path(source)
    if not path.exists():
        raise DevModeRefused(MISSING.format(path=_q(source)))
    if path.is_dir():
        entry = path / "main.py"
        if not entry.is_file():
            raise DevModeRefused(PREBUILT.format(path=_q(source)))
        return entry, path
    if path.is_file() and path.suffix == ".py":
        return path, path
    raise DevModeRefused(NOT_SOURCE.format(path=_q(source)))


def _project_namespace(entry: Path) -> str:
    # The name a release of this project is built under: workpeg.json's
    # namespace first, then the folder. The same function the build calls,
    # kept quiet about a stray workpeg.json: a refusal is one line, and the
    # build that follows a pass says it anyway.
    from workpeg.ui.build import _peg_namespace

    namespace = _peg_namespace(str(entry), warn=False)
    if not namespace:
        raise DevModeRefused(NO_NAMESPACE)
    if is_refused_label(namespace):
        raise DevModeRefused(REFUSED_NAME.format(name=_q(namespace)))
    return namespace


def preflight(
    source: str,
    *,
    peg_namespace: "str | None",
    port: int,
    environ: Mapping[str, str],
) -> DevPlan:
    """Check everything dev mode can check on this machine, or refuse.

    Reads files and one environment variable by name. It binds nothing,
    resolves no name and opens no connection, so a refusal leaves nothing
    behind. *port* is ``--port``, where 0 means it was not given.
    """
    if peg_namespace is not None:
        raise DevModeRefused(PEG_NAMESPACE)
    if port not in (0, DEV_PORT):
        raise DevModeRefused(PORT_REFUSED)
    if BIND_HOST_ENV in environ:
        raise DevModeRefused(BIND_HOST_REFUSED)
    entry, watch = _source(source)
    return DevPlan(entry=entry, watch=watch,
                   namespace=_project_namespace(entry))
